using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace AiBox.DevPortal.Services
{
    public class ContextSuggestionService
    {
        public ContextSuggestionService()
        {
        }

        public IReadOnlyList<string> SuggestFiles(string userRequest, ProjectKnowledgeIndex knowledgeIndex)
        {
            userRequest = userRequest.ToLower().Split(' ').Select(token => token.Trim()).Where(token => !string.IsNullOrEmpty(token)).ToList();

            var scores = knowledgeIndex.Items.Select(item =>
            {
                int score = 0;
                score += item.RelativePath.ToLower().Split('/').Select(segment => userRequest.Contains(segment.ToLower())).Count(segment => segment);
                score += item.Namespace.ToLower().Split('.').Select(segment => userRequest.Contains(segment.ToLower())).Count(segment => segment);
                score += item.Classes.ToLower().Split(',').Select(segment => userRequest.Contains(segment.ToLower())).Count(segment => segment);
                score += item.Interfaces.ToLower().Split(',').Select(segment => userRequest.Contains(segment.ToLower())).Count(segment => segment);
                score += item.Records.ToLower().Split(',').Select(segment => userRequest.Contains(segment.ToLower())).Count(segment => segment);
                return new { item.RelativePath, score };
            }).ToList();

            scores.Sort((a, b) => b.score.CompareTo(a.score));

            return scores.Take(10).Select(score => score.RelativePath).ToList();
        }
    }
}
